let user = try! await api.user(id)

// structured: guards up front, one error path
func load(_ id: String) async -> Result<User, LoadError> {
  guard let r = try? await api.user(id) else { return .failure(.unreachable) }
  guard r.isActive else { return .failure(.inactive) }
  return .success(User(r))
}
